  source_inputs: ledger,                                    // source ledger (sources + spans)
  claim_inputs: (ledger && ledger.claims) || null,          // claim records
  asset_inputs: fields['Image Manifest'] || null,           // asset manifest
  editorial_inputs: fields['Analysis of the Prospect'] || null, // editorial analysis
  composition_inputs: fields['report_json'] || null,        // composition payload
};

const body = JSON.stringify(runInputs, null, 2);
const runInputsSha256 = crypto.createHash('sha256').update(body, 'utf8').digest('hex');
const fileName = `REVIEW_${record.id}_run-inputs.json`;

return [{
  json: {
    ...$json,
    record_id: record.id,
    run_inputs_sha256: runInputsSha256,
    run_inputs_file_name: fileName,
  },
  binary: {
    data: {
      data: Buffer.from(body, 'utf-8').toString('base64'),
      mimeType: 'application/json',
      fileName: fileName,
    },
  },
}];

// ═══════════════════════════════════════════════════════════════
// BUILD RENDERER ENVELOPE v3 (review) — derived from "Build Renderer Payload"
// Assembles the canonical /render-v3 envelope:
//   {payload, images, brand_tokens}
//   + the six workflow version fields
//   + workflow_verification_v3 (five artifacts + verification_bundle_sha256)
// REVIEW-ONLY workflow: never promotes to production.
// ═══════════════════════════════════════════════════════════════

const crypto = require('crypto');

// The canonical six-field version handshake (docs/n8n/workflow-contract-v3.json).
const WORKFLOW_VERSIONS_V3 = Object.freeze({
  workflow_contract_version: "3.2.1",
  writer_prompt_version: "5.1.1",
  schema_resolver_version: "5.2.1",
  writer_gate_version: "3.1.1",
  source_ledger_version: "3.2.1",
  claim_gate_version: "3.2.1",
});

// Byte hashes of the five paste-target artifacts embedded in THIS workflow.
// They must match contract 3.2.1 exactly or /render-v3 returns 409.
const WORKFLOW_ARTIFACTS_V3 = [
  {
    artifact_id: "writer_prompt",
    semantic_version: "5.1.1",
    sha256: "2c13d8e1c0978c62d4b4ff68f62d3a6888a1bb89d462e41c2d2a21a96ef63fb4",
    expected_node_name: "Section Writer v5",
    input_schema_version: "section-data-v3",
    output_schema_version: "writer-section-v5",
  },
  {
