    semantic_version: "5.2.1",
    sha256: "200c72381eb9a924e1da369b4c2ee1dfd5509ad0cb5a6dc06a263d9a563a339a",
    expected_node_name: "Resolve Schema and Build Prompts v5",
    input_schema_version: "chapter-item-v5",
    output_schema_version: "writer-prompt-item-v5",
  },
  {
    artifact_id: "writer_gate",
    semantic_version: "3.1.1",
    sha256: "cff8b26e96bb7e7754b07615e8fe333a4c8edb792ac90210129da881e103068a",
    expected_node_name: "Writer Gate v3",
    input_schema_version: "writer-section-v5",
    output_schema_version: "gated-section-v3",
  },
  {
    artifact_id: "source_ledger",
    semantic_version: "3.2.1",
    sha256: "95b27737adf7421eb4603881fee78cdc8401fdf93619a71608f7c0ea916463dc",
    expected_node_name: "Source Ledger v3",
    input_schema_version: "raw-client-evidence-v3",
    output_schema_version: "source-ledger-v3",
  },
  {
    artifact_id: "claim_gate",
    semantic_version: "3.2.1",
    sha256: "19e2158cea55010105d078e9f9b93d362173dca76a4d34796c1907a8d9e115fe",
    expected_node_name: "Claim Gate v3",
    input_schema_version: "writer-section-v5+source-ledger-v3",
    output_schema_version: "claim-gated-section-v3",
  }
];

// Canonical sorted compact JSON — must equal python json.dumps(sort_keys=True,
// separators=(",", ":")) in dmc-renderer/service.py (all values are ASCII).
function sortKeysDeep(value) {
  if (Array.isArray(value)) return value.map(sortKeysDeep);
  if (value && typeof value === 'object') {
    return Object.keys(value).sort().reduce((acc, key) => {
      acc[key] = sortKeysDeep(value[key]);
      return acc;
    }, {});
  }
  return value;
}
function canonicalJson(value) {
  return JSON.stringify(sortKeysDeep(value));
}

const record = $('Airtable: Get Content Record (review)').first().json;
const fields = record.fields || record;

// ─── payload / images / brand_tokens (same derivation as the v2 node) ───
let reportPayload;
try {
  const raw = fields['report_json'] || fields.report_json;
  reportPayload = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (e) {
  throw new Error(`Failed to parse report_json: ${e.message}`);
}

let imageManifest;
try {
  const raw = fields['Image Manifest'] || fields.image_manifest;
  imageManifest = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (e) {
  imageManifest = { images: [] };
}

const images = {};
if (imageManifest && Array.isArray(imageManifest.images)) {
  for (const img of imageManifest.images) {
    if (img.url && img.status !== 'skipped' && img.status !== 'blocked') {
      images[img.id] = img.url;
    }
  }
}

const client = fields['Client'] || fields.client || 'Unknown';
const clientSlug = client.toLowerCase().replace(/[^a-z0-9]/g, '-').replace(/-+/g, '-');

const brandTokens = {
  brand_primary: '#1a1a2e',
  brand_accent: '#e94560',
  brand_neutral_dark: '#0f0f1f',
  brand_neutral_mid: '#7a7a8c',
  brand_neutral_light: '#f5f5f7',
  font_heading: 'Inter',
  font_body: 'Source Serif Pro',
  logo_dark_url: images['about_logo'] || '',
  logo_light_url: images['about_logo'] || '',
  qr_target_url: reportPayload?.pages?.find(p => p.type === 'ST-03')?.data?.cta_url || '',
  founder_full_name: '',
  founder_role: '',
  company_name_short: client,
  company_url_display: ''
};

// ─── workflow_verification_v3 (hash computed the way service.py checks it) ───
const unsignedBundle = {
  schema_version: '1.0',
  workflow_contract_version: WORKFLOW_VERSIONS_V3.workflow_contract_version,
  artifacts: WORKFLOW_ARTIFACTS_V3,
};
const verificationBundleSha256 = crypto
  .createHash('sha256')
  .update(canonicalJson(unsignedBundle), 'utf8')
  .digest('hex');
const workflowVerificationV3 = {
  ...unsignedBundle,
  verification_bundle_sha256: verificationBundleSha256,
};

// ─── run-scoped identity: reused verbatim on every HTTP retry, so a retried
// render can never mint a second artifact identity or duplicate an upload ───
const recordId = record.id;
const idempotencyKey = `idem-dmc-v3-review-${$execution.id}-${recordId}`;
const correlationId = `corr-dmc-v3-review-${$execution.id}-${recordId}`;

const envelope = {
  payload: reportPayload,
  images: images,
  brand_tokens: brandTokens,
  ...WORKFLOW_VERSIONS_V3,
  workflow_verification_v3: workflowVerificationV3,
};

return [{
  json: {
    render_v3_body: envelope,
    render_v3_body_string: JSON.stringify(envelope),
    render_idempotency_key: idempotencyKey,
    render_correlation_id: correlationId,
    record_id: recordId,
    content_id: fields['Content ID'] || fields.content_id || '',
    client: client,
    client_slug: clientSlug,
    review_only: true,
  },
}];

// /render-v3 answered 422 rejected (JSON body, no PDF). REVIEW-ONLY branch.
const json = $input.first().json || {};
const headers = json.headers || {};
const body = (typeof json.body === 'object' && json.body) || {};
const envelope = $('Build Renderer Envelope v3 (review)').first().json;

return [{
  json: {
    review_only: true,
    record_id: envelope.record_id,
    render_correlation_id: envelope.render_correlation_id,
    render_status: 'review-rejected (REVIEW-ONLY)',
    release_state: body.release_state || headers['x-dmc-release-state'] || 'rejected',
    failure_count: (body.failures || []).length,
    gate_report_sha256: headers['x-dmc-gate-report-sha256'] || '',
    artifact_manifest_sha256: headers['x-dmc-artifact-manifest-sha256'] || '',
  },
}];

// /render-v3 answered 202 draft (JSON body, no delivery PDF). REVIEW-ONLY branch.
